args.CodeContent:
.login-auth-screen {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.login-auth-card {
  position: relative;
  width: 100%;
  max-width: 720px;
  background-color: hsla(0, 0%, 100%, 0.2);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 64px 32px 32px;
  text-align: center;
}

.login-logo-container {
  position: absolute;
  top: -32px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.login-logo-container img {
  height: 64px;
}

.login-auth-heading {
  font-weight: 600;
  font-size: 26px;
  line-height: 1.25;
  margin: 8px 0 6px;
}

.login-auth-subtext {
  font-size: 14px;
  color: var(--text-muted);
  margin: 0 0 32px;
  line-height: 1.5;
}

.login-auth-form {
  display: flex;
  flex-direction: column;
  gap: 32px;
  text-align: left;
}

.login-auth-form > div:nth-child(1) {
  display: flex;
  flex-direction: row;
  gap: 16px;
}

.login-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.login-input-primary {
  width: 320px;
}

.login-input--error {
  border-color: var(--error);
}

.login-input-with-action {
  position: relative;
  display: flex;
  align-items: center;
}

.login-field-error {
  font-size: 12.5px;
  color: var(--error);
  margin: 2px 4px 0;
}

.login-btn-primary.disabled {
  color: var(--text-disabled);
  cursor: not-allowed;
}

.login-auth-footer {
  margin: 32px 0 0;
  font-size: 14px;
  color: var(--text-more-muted);
}

.login-auth-footer a {
  color: var(--secondary);
  font-weight: 500;
  text-decoration: none;
  transition: 0.2s all ease-in-out;
}

.login-auth-footer a:hover {
  color: var(--primary);
  text-decoration: underline;
}

.login-spinner {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #fff;
  animation: login-spin 0.7s linear infinite;
}

@keyframes login-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .login-spinner {
    animation-duration: 1.4s;
  }
}

@media (max-width: 420px) {
  .login-auth-card {
    padding: 51px 24px 24px;
  }

  .login-logo-container {
    top: -27px;
  }

  .login-auth-subtext {
    font-size: 12px;
    margin: 0 0 24px;
  }

  .login-logo-container img {
    height: 54px;
  }

  .login-auth-form {
    gap: 24px;
  }

  .login-auth-form label {
    display: none;
  }

  .login-auth-form > div:nth-child(1) {
    flex-direction: column;
  }

  .login-input-primary {
    width: 303px;
  }

  .login-auth-footer {
    font-size: 12px;
    margin: 24px 0 0;
  }
}

args.ReplacementContent:
  return (
    <div className="login-auth-screen">
      <div className="login-auth-card">
        <div className="login-logo-container">
          <img src="https://res.cloudinary.com/diwkfbsgv/image/upload/v1775206748/logo_u4sz9t.svg" />
        </div>

        <h1 className="login-auth-heading">Welcome back!</h1>
        <p className="login-auth-subtext">
          We'll get you right back to where you left off
        </p>

        <form className="login-auth-form" onSubmit={handleSubmit} noValidate>
          <div>
            <div className="login-field">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                placeholder="zawadi@company.com"
                value={form.email}
                onChange={handleChange}
                onBlur={handleBlur}
                aria-invalid={Boolean(showError("email"))}
                aria-describedby={
                  showError("email") ? "email-error" : undefined
                }
                className={
                  showError("email")
                    ? "login-input-primary login-input--error"
                    : "login-input-primary"
                }
              />
              {showError("email") && (
                <p className="login-field-error" id="email-error">
                  {errors.email}
                </p>
              )}
            </div>

            <div className="login-field">
              <label htmlFor="password">Password</label>
              <div className="login-input-with-action">
                <input
                  id="password"
                  name="password"
                  autoComplete="login-password"
                  placeholder="Enter password"
                  value={form.password}
                  onChange={handleChange}
                  onBlur={handleBlur}
                  aria-invalid={Boolean(showError("password"))}
                  aria-describedby={
                    showError("password") ? "password-error" : undefined
                  }
                  className={
                    showError("password")
                      ? "login-input-primary login-input--error"
                      : "login-input-primary"
                  }
                />
              </div>
              {showError("password") && (
                <p className="login-field-error" id="password-error">
                  {errors.password}
                </p>
              )}
            </div>
          </div>

          <button
            type="submit"
            className={`login-submit-btn btn-primary ${isSubmitting || isSuccess ? "disabled" : ""}`}
            disabled={isSubmitting || isSuccess}
          >
            {isSubmitting ? <Spinner /> : "Continue to dashboard"}
          </button>
        </form>

        <p className="login-auth-footer">
          New here? <a href="/">Create account</a>
        </p>
      </div>
      {apiError && <SuccessToast subtext={apiError} success="red" />}
      {isSuccess && (
        <SuccessToast
          title={`Welcome Back, ${form.email.trim()}!`}
          subtext="Taking you to your dashboard..."
          success="green"
        />
      )}
    </div>
  );
}

function Spinner() {
  return <span className="login-spinner" aria-hidden="true" />;
}

